mapper.select:
SELECT a.id, a.beacon_id, a.beacon_type, a.control_type, a.location, a.map_coord, a.pixel_x, a.pixel_y, a.gps_coord, a.gps_longitude, a.gps_latitude, a.beacon_status, a.deploy_status, a.create_by, a.create_date, a.update_by, a.update_date, a.remarks FROM swm_beacon_station a WHERE a.status = '0'
AND a.gps_longitude >= #{minLongitude}
AND a.gps_longitude <= #{maxLongitude}
AND a.gps_latitude >= #{minLatitude}
AND a.gps_latitude <= #{maxLatitude}
ORDER BY a.update_date DESC

SELECT a.id, a.beacon_id, a.beacon_type, a.control_type, a.location, a.map_coord, a.pixel_x, a.pixel_y, a.gps_coord, a.gps_longitude, a.gps_latitude, a.beacon_status, a.deploy_status, a.create_by, a.create_date, a.update_by, a.update_date, a.remarks FROM swm_beacon_station a WHERE a.status = '0'
AND a.pixel_x >= #{minX}
AND a.pixel_x <= #{maxX}
AND a.pixel_y >= #{minY}
AND a.pixel_y <= #{maxY}
ORDER BY a.update_date DESC
